		},
		{
			desc:          "TELEPORT_SITE and TELEPORT_CLUSTER set, prefer TELEPORT_CLUSTER",
			inCLIConf:     CLIConf{},
			inSiteName:    "c.example.com",
			inClusterName: "d.example.com",
			outSiteName:   "d.example.com",
